"use strict";(self.webpackChunkudonarium=self.webpackChunkudonarium||[]).push([[1636],{47961(e){e.exports=JSON.parse('{"ko_kr":{"BlackJacket":{"action_judge":"\ud589\uc704\ud310\uc815(\uc131\uacf5\ub960:%<rate>d\uff05)","fumble":"\uc2e4\ud328 \uff1e \ud38c\ube14! \ud30c\uc6cc\uc758 \ub300\uac00(\ucf54\uc2a4\ud2b8) 2\ubc30 & \uc7ac\uad74\ub9bc \ubd88\uac00","critical":"\uc131\uacf5 \uff1e \ud06c\ub9ac\ud2f0\uceec! \ud30c\uc6cc\uc758 \ub300\uac00(\ucf54\uc2a4\ud2b8) \uc808\ubc18\uc73c\ub85c \uac10\uc18c","misery":"\uc2e4\ud328 \uff1e \ubbf8\uc800\ub9ac! \ud30c\uc6cc\uc758 \ub300\uac00(\ucf54\uc2a4\ud2b8) 2\ubc30 & \uc7ac\uad74\ub9bc \ubd88\uac00","death_chart_result":"\ub370\uc2a4 \ucc28\ud2b8\uff08%<name>s\uff09[\ub9c8\uc774\ub108\uc2a4 \uac12:%<minus>d + 1D10(->%<dice>d) = %<key>d] \uff1e %<key_text>s \uff1a %<chosen>s","death_chart_under":"10\uc774\ud558","death_chart_over":"20\uc774\uc0c1","chart_name":{"physical":"\uc721\uccb4","mental":"\uc815\uc2e0","social":"\ud658\uacbd"},"death_charts":{"physical":["\ud6a8\uacfc \uc5c6\uc74c. \ub2f9\uc2e0\uc740 \uae30\uc801\uc801\uc73c\ub85c \ubaa9\uc228\uc744 \uac74\uc84c\ub2e4. \uc2f8\uc6c0\uc740 \uacc4\uc18d\ub41c\ub2e4.","\uaca9\ud55c \ud1b5\uc99d\uc744 \ub290\ub080\ub2e4. \uc774\ud6c4 \uc774\ubca4\ud2b8\uac00 \ub05d\ub0a0 \ub54c\uae4c\uc9c0 \ubaa8\ub4e0 \ud310\uc815\uc758 \uc131\uacf5\ub960\uc5d0 -10%.","\ub354\uc774\uc0c1 \ubab8\uc774 \uc6c0\uc9c1\uc774\uc9c0 \uc54a\ub294\ub2e4\u2026\u2026 \ub2f9\uc2e0\uc740 [\uacbd\uc9c1 2]\ub97c \ubc1b\ub294\ub2e4.","\ud63c\uc2e0\uc758 \uc77c\uaca9!! \ub2f9\uc2e0\uc740 \u3008\uc0dd\uc874\u3009 \ud310\uc815\uc744 \ud55c\ub2e4. \uc2e4\ud328\ud560 \uacbd\uc6b0 [\uc0ac\ub9dd]\ud55c\ub2e4.","\uac11\uc790\uae30 \ub208\uc55e\uc774 \uce84\uce84\ud574\uc9c4\ub2e4. \ub2f9\uc2e0\uc740 [\uae30\uc808 2]\ub97c \ubc1b\ub294\ub2e4.","\uc774\ud6c4, \uc774\ubca4\ud2b8 \uc885\ub8cc\uae4c\uc9c0 \ubaa8\ub4e0 \ud310\uc815\uc758 \uc131\uacf5\ub960 -20%.","\uae30\ub85d\uc801\uc778 \uc77c\uaca9!! \ub2f9\uc2e0\uc740 \u3008\uc0dd\uc874\u3009 -20% \uc73c\ub85c \ud310\uc815\ud55c\ub2e4. \uc2e4\ud328\ud560 \uacbd\uc6b0 [\uc0ac\ub9dd]\ud55c\ub2e4.","\uc0ac\ub290\ub0d0 \uc8fd\ub290\ub0d0. \ub2f9\uc2e0\uc740 [\ube48\uc0ac 2]\ub97c \ubc1b\ub294\ub2e4.","\uc5ed\uc0ac\uc5d0 \ud55c \ud68d\uc744 \uadf8\uc744 \uc77c\uaca9!! \ub2f9\uc2e0\uc740 <\uc0dd\uc874> -30% \uc73c\ub85c \ud310\uc815\ud55c\ub2e4. \uc2e4\ud328\ud560 \uacbd\uc6b0 [\uc0ac\ub9dd]\ud55c\ub2e4.","\uc774\ud6c4, \uc774\ubca4\ud2b8 \uc885\ub8cc \uc2dc\uae4c\uc9c0 \ubaa8\ub4e0 \ud310\uc815\uc758 \uc131\uacf5\ub960 -30%.","\uc2e0\ud654\uc801 \uc77c\uaca9!! \uacf5\uc911\uc5d0\uc11c \uc138 \ubc14\ud034 \uc815\ub3c4 \ud68c\uc804\ud55c \ud6c4 \ub545\ubc14\ub2e5\uc5d0 \ub0b4\ub3d9\ub315\uc774\uccd0\uc9c4\ub2e4. \ubcf4\uae30\uc5d0\ub3c4 \ub054\ucc0d\ud55c \ubaa8\uc2b5. \uc721\uccb4\ub294 \uc6d0\ud615\uc744 \uc720\uc9c0\ud558\uc9c0 \ubabb\ud588\ub2e4. \ub2f9\uc2e0\uc740 [\uc0ac\ub9dd]\ud55c\ub2e4."],"mental":["\ud6a8\uacfc \uc5c6\uc74c. \ub2f9\uc2e0\uc740 \uc774\ub97c \uc545\ubb3c\uace0 \uc2a4\ud2b8\ub808\uc2a4\ub97c \uacac\ub38c\ub0c8\ub2e4.","\uc774\ud6c4, \uc774\ubca4\ud2b8 \uc885\ub8cc \uc2dc\uae4c\uc9c0 \ubaa8\ub4e0 \ud310\uc815\uc758 \uc131\uacf5\ub960 -10%.","\ub9d0\ud560 \uc218 \uc5c6\ub294 \uacf5\ud3ec\uac00 \ub2f9\uc2e0\uc744 \uc5c4\uc2b5\ud55c\ub2e4. \ub2f9\uc2e0\uc740 [\uacf5\ud3ec 2]\ub97c \ubc1b\ub294\ub2e4.","\uc0c1\ucc98\ub97c \ub9ce\uc774 \ubc1b\uc558\ub2e4. \ub2f9\uc2e0\uc740 \u3008\uc758\uc9c0\u3009 \ud310\uc815\uc744 \ud55c\ub2e4. \uc2e4\ud328\ud560 \uacbd\uc6b0 [\uc808\ub9dd] \uc0c1\ud0dc\uac00 \ub418\uc5b4\uc11c NPC\uac00 \ub41c\ub2e4.","\uc758\uc2dd\uc744 \uc783\uc5c8\ub2e4. \ub2f9\uc2e0\uc740 [\uae30\uc808 2]\ub97c \ubc1b\ub294\ub2e4.","\uc774\ud6c4, \uc774\ubca4\ud2b8 \uc885\ub8cc \uc2dc\uae4c\uc9c0 \ubaa8\ub4e0 \ud310\uc815\uc758 \uc131\uacf5\ub960 -20%.","\uc2e0\ub8b0\ud588\ub358 \uc790\uc5d0\uac8c \uc18d\uc740 \uc544\ud514. \ub2f9\uc2e0\uc740 \u3008\uc758\uc9c0\u3009 -20% \uc73c\ub85c \ud310\uc815\ud55c\ub2e4. \uc2e4\ud328\ud560 \uacbd\uc6b0, [\uc808\ub9dd] \uc0c1\ud0dc\uac00 \ub418\uc5b4\uc11c NPC\uac00 \ub41c\ub2e4.","\ub3d9\ub8cc\uc5d0\uac8c \ubc30\uc2e0 \ub2f9\ud55c \uac83\uc77c\uc9c0\ub3c4 \ubaa8\ub978\ub2e4. \ub2f9\uc2e0\uc740 [\ud63c\ub780 2]\ub97c \ubc1b\ub294\ub2e4.","\ub108\ubb34\ub098 \ucc38\ud639\ud55c \ud604\uc2e4. \ub2f9\uc2e0\uc740 \u3008\uc758\uc9c0\u3009 -30% \uc73c\ub85c \ud310\uc815\ud55c\ub2e4. \uc2e4\ud328\ud560 \uacbd\uc6b0 [\uc808\ub9dd] \uc0c1\ud0dc\uac00 \ub418\uc5b4\uc11c NPC\uac00 \ub41c\ub2e4.","\uc774\ud6c4, \uc774\ubca4\ud2b8 \uc885\ub8cc \uc2dc\uae4c\uc9c0 \ubaa8\ub4e0 \ud310\uc815\uc758 \uc131\uacf5\ub960 -30%.","\ucc9c\uc9c0\uac1c\ubcbd\uc758 \uc774\uce58 \uadf8 \uc774\uc0c1. \uadf8\uac83\uc740 \uc778\ub958\uc758 \uc778\uc2dd\ud55c\uacc4\ub97c \ub6f0\uc5b4\ub118\ub294 \ubb34\uc5b8\uac00\uc600\ub2e4. \ub2f9\uc2e0\uc740 [\uc808\ub9dd] \uc0c1\ud0dc\uac00 \ub41c \ud6c4 NPC\uac00 \ub41c\ub2e4."],"social":["\ud6a8\uacfc \uc5c6\uc74c. \ub2f9\uc2e0\uc740 \ub4a4\uc22d\uc22d\ud55c \uc18c\ubb38\uc744 \ubb34\uc2dc\ud588\ub2e4.","\uc774\ud6c4, \uc774\ubca4\ud2b8 \uc885\ub8cc \uc2dc\uae4c\uc9c0 \ubaa8\ub4e0 \ud310\uc815\uc758 \uc131\uacf5\ub960 -10%.","\uc704\ud5d8\ud55c \uc0c1\ud0dc! \uc774\ud6c4, \ub77c\uc6b4\ub4dc \uc885\ub8cc \uc2dc\uae4c\uc9c0 \ub2f9\uc2e0\uc740 \uce74\ub974\ub9c8\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc5c6\ub2e4.","\ub098\uc05c \uc18c\ubb38\uc774 \ub3c8\ub2e4. \ub2f9\uc2e0\uc740 \u3008\uad50\uc12d\u3009 \ud310\uc815\uc744 \ud55c\ub2e4. \uc2e4\ud328\ud560 \uacbd\uc6b0 \ub2f9\uc2e0\uc740 \ub3d9\ub8cc\ub4e4\uc758 \uc2e0\ub8b0\ub97c \uc783\uace0 [\ubb34\uc5f0\uace0] \uc0c1\ud0dc\uac00 \ub41c \ud6c4 NPC\uac00 \ub41c\ub2e4.","\uc774\ud6c4, \uc2dc\ub098\ub9ac\uc624 \uc885\ub8cc \uc2dc\uae4c\uc9c0 \ub300\uac00(\ucf54\uc2a4\ud2b8)\uc5d0 \ud06c\ub808\ub527\uc744 \uc18c\ube44\ud558\ub294 \ud30c\uc6cc\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc5c6\ub2e4.","\ub2f9\uc2e0\uc758 \uc545\ud3c9\uc774 \uc138\uc0c1\uc5d0 \ub110\ub9ac \uc54c\ub824\uc9c4\ub2e4. \ud611\ub825\uc790\ub85c\ubd80\ud130\uc758 \uc9c0\uc6d0\uc774 \uc911\ub2e8\ub41c\ub2e4. \uc774\ud6c4 \uc2dc\ub098\ub9ac\uc624 \uc885\ub8cc \uc2dc\uae4c\uc9c0 \ubaa8\ub4e0 \ud310\uc815\uc758 \uc131\uacf5\ub960 -20%.","\ubc30\uc2e0!! \ub2f9\uc2e0\uc740 \u3008\uacbd\uc81c\u3009 -20% \uc73c\ub85c \ud310\uc815\ud55c\ub2e4. \uc2e4\ud328\ud560 \uacbd\uc6b0 \ub2f9\uc2e0\uc740 \uc8fc\uc704\ub85c\ubd80\ud130 \uc2e0\uc6a9\uc744 \uc783\uace0, [\ubb34\uc5f0\uace0] \uc0c1\ud0dc\uac00 \ub418\uc5b4 NPC\uac00 \ub41c\ub2e4.","\uc774\ud6c4, \uc2dc\ub098\ub9ac\uc624 \uc885\ub8cc \uc2dc\uae4c\uc9c0 \u3010\ud658\uacbd\u3011 \uacc4\uc5f4\uc758 \uae30\ub2a5 \ub808\ubca8\uc774 \ubaa8\ub450 0\uc774 \ub41c\ub2e4.","\ub0a0\uc870 \ubcf4\ub3c4? \uae30\uc5b5\ub098\uc9c0 \uc54a\ub294 \ubc30\uc2e0 \ud589\uc704\uac00 \ud2b9\uc885\uc73c\ub85c \ubcf4\ub3c4\ub41c\ub2e4. \ub2f9\uc2e0\uc740 \u3008\uc2ec\ub9ac\u3009 -30% \uc73c\ub85c \ud310\uc815\ud55c\ub2e4. \uc2e4\ud328\ud560 \uacbd\uc6b0 \ub2f9\uc2e0\uc740 \uc778\uac04\uc73c\ub85c\uc11c\uc758 \uc874\uc5c4\uc131\uc744 \uc783\uace0, [\ubb34\uc5f0\uace0]\uac00 \ub41c\ub2e4.","\uc774\ud6c4, \uc774\ubca4\ud2b8 \uc885\ub8cc \uc2dc\uae4c\uc9c0 \ubaa8\ub4e0 \ud310\uc815 \uc131\uacf5\ub960 -30%.","\ub2f9\uc2e0\uc758 \uc774\ub984\uc740 \uc0ac\uc0c1 \ucd5c\uc545\uc758 \uc624\uc810\uc73c\ub85c \uc601\uc6d0\ud788 \uc5ed\uc0ac\uc5d0 \uc0c8\uaca8\uc9c4\ub2e4. \uc774\uc81c \ub2f9\uc2e0\uc744 \ubbff\ub294 \ub3d9\ub8cc\ub294 \uc5c6\uace0 \ub2f9\uc2e0\uc744 \ub3d5\ub294 \uc0ac\ud68c\ub3c4 \uc5c6\ub2e4. \ub2f9\uc2e0\uc740 [\ubb34\uc5f0\uace0] \uc0c1\ud0dc\uac00 \ub41c \ud6c4 NPC\uac00 \ub41c\ub2e4."]},"table":{"CPC":{"name":"\ucc4c\ub9b0\uc9c0\u30fb\ud328\ub110\ud2f0 \ucc28\ud2b8","type":"1D10","items":["\uc0ac\ub9dd\\n\ub3c4\uc640\uc57c \ud560 NPC (\ud788\ub85c\uc778 \ub4f1)\uac00 \uc0ac\ub9dd\ud55c\ub2e4.","\ud751\uc131\\n\uc801\uc774 \ubaa9\uc801\uc744 \uc131\ucde8\ud558\uace0, \uc0ac\uac74\uc740 PC\uc758 \ud328\ubc30\ub85c \ub05d\ub09c\ub2e4. \uadf8\ub300\ub85c \uc5ec\uc6b4 \ud398\uc774\uc988\ub85c \ub118\uc5b4\uac08 \uac83.","\ud65c\uc131\\n\uc801 \ubcf4\uc2a4\uc758 \ub77c\uc774\ud504\ub97c 2\ubc30\ub85c \ud55c \ub2e4\uc74c \uacb0\uc804 \ud398\uc774\uc988\ub97c \uac1c\uc2dc\ud55c\ub2e4.","\uacf5\uc138\\n\uc801 \ubcf4\uc2a4\uc758 \ub300\ubbf8\uc9c0\uc5d0 +2D6\uc758 \uc218\uc815\uc744 \uc900 \ud6c4 \uacb0\uc804 \ud398\uc774\uc988\ub97c \uac1c\uc2dc\ud55c\ub2e4.","\ub300\uac70\\n\uc801\uc758 \uc218(\ubcf4\uc2a4 \uc81c\uc678)\ub97c 2\ubc30\ub85c \ud55c \ud6c4 \uacb0\uc804 \ud398\uc774\uc988\ub97c \uac1c\uc2dc\ud55c\ub2e4.","\uc554\ud751\\n\ubaa8\ub4e0 \uc5d0\ub9ac\uc5b4(\uad6c\uc5ed)\uc744 [\uc5b4\ub460]\uc73c\ub85c \ub9cc\ub4e0 \ub2e4\uc74c \uacb0\uc804 \ud398\uc774\uc988\ub97c \uac1c\uc2dc\ud55c\ub2e4.","\ub9f9\ud654\\n\uc804\ud22c \uc5d0\ub9ac\uc5b4(\uad6c\uc5ed) 2\uac1c\ub97c [\ub300\ubbf8\uc9c0 \uc874 2]\ub85c \ucde8\uae09\ud55c \ud6c4, \uacb0\uc804 \ud398\uc774\uc988\ub97c \uac1c\uc2dc\ud55c\ub2e4.","\ubcf5\ubcd1\\n\uc801\uc758 \uc808\ubc18\uc744 \uc5d0\ub9ac\uc5b4(\uad6c\uc5ed) 1\uacfc \uc5d0\ub9ac\uc5b4(\uad6c\uc5ed) 2\ub85c \uc774\ub3d9\uc2dc\ud0a8 \ud6c4, \uacb0\uc804 \ud398\uc774\uc988\ub97c \uac1c\uc2dc\ud55c\ub2e4.","\ub9cc\ubcf5\\n\ubcf4\uc2a4 \uc774\uc678\uc758 \uc801\uc758 \ub77c\uc774\ud504\ub97c \ubaa8\ub450 2\ubc30\ub85c \ud55c \ub2e4\uc74c, \uacb0\uc804 \ud398\uc774\uc988\ub97c \uac1c\uc2dc\ud55c\ub2e4.","\ubd09\uc778\\nPC\ub294 \uacb0\uc804 \ud398\uc774\uc988 \ub3d9\uc548 \uce74\ub974\ub9c8\ub97c \uc0ac\uc6a9\ud560 \uc218 \uc5c6\ub2e4. \uacb0\uc804 \ud398\uc774\uc988\ub97c \uac1c\uc2dc\ud55c\ub2e4."]},"STC":{"name":"\uc0ac\uc774\ub4dc \ud2b8\ub799 \ucc28\ud2b8","type":"1D10","items":["\ud574\ud6c4\\n\uc6b0\uc5f0\ud788 NPC\uc640 \ub9cc\ub09c\ub2e4. \uc5b4\ub5a4 NPC\uac00 \ub098\ud0c0\ub0a0\uc9c0\ub294 GM\uc774 \uacb0\uc815\ud55c\ub2e4.","\uc0ac\uace0\\n\uad50\ud1b5\uc0ac\uace0\ub97c \ub2f9\ud55c\ub2e4. \uc8fc\ubcc0\uc5d0\uc11c \ud328\ub2c9\uc774 \uc77c\uc5b4\ub098\uace0 \uc788\uc744\uc9c0\ub3c4 \ubaa8\ub978\ub2e4.","\ub0ae\uc7a0\\n\uc9c0\ub3c5\ud55c \uc878\uc74c\uc774 \ubab0\ub824\uc628\ub2e4. \uc124\ub9c8, \uc2e0\ucc38 \ube4c\ub7f0\uc758 \ub2a5\ub825\uc778\uac00?","\uace0\ubc31\\nNPC \ud55c \uba85\uc774 \uc9c0\uae08\uae4c\uc9c0 \uac04\uc9c1\ud558\uace0 \uc788\ub358 \ub9c8\uc74c\uc744 \ub2f9\uc2e0\uc5d0\uac8c \uace0\ubc31\ud55c\ub2e4.","\uc124\uc815\\n\uc0c8\ub85c\uc6b4 \uc124\uc815\uc774 \ubc1d\ud600\uc9c4\ub2e4. \uc0ac\uc2e4\uc740 NPC\uc758 \uc544\ubc84\uc9c0\uc600\ub2e4\ub4e0\uac00, \uc120\ucc9c\uc801\uc73c\ub85c \ub208\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294\ub2e4\ub4e0\uac00.","\uc790\uac1d\\n\ub204\uad70\uac00\ub85c\ubd80\ud130 \uacf5\uaca9\uc744 \ubc1b\ub294\ub2e4. \uc81c3\uc138\ub825\uc778\uac00?","\ubd88\uccad\uac1d\\n\uc6b0\uc5f0\ud788 \uc6d0\uc218 \ud55c \uba85\uacfc \ub9c8\uc8fc\uce5c\ub2e4. \uc0c1\ud669\uc5d0 \ub530\ub77c\uc11c \ubc14\ub85c \uc804\ud22c\uac00 \ubc1c\uc0dd\ud560\uc9c0\ub3c4 \ubaa8\ub978\ub2e4.","\uc758\uc2ec\\n\uc218\uc0c1\ud55c \uc0ac\ub78c\uc744 \ub208\uce58\ucc58\ub2e4. \ub530\ub77c\uac00\uc57c \ud558\ub098? \ubb34\uc2dc\ud574\uc57c \ud558\ub098?","\uc870\uc6b0\\n\uc2dc\ub098\ub9ac\uc624\uc640 \uad00\uacc4\uc5c6\ub294 \ube4c\ub7f0 \uc870\uc9c1\uacfc \uc870\uc6b0\ud55c\ub2e4.","\ud3c9\ud654\\n\ubcc4\uc77c \uc5c6\uc5c8\ub2e4."]}}}}}')}}]);